import json
import math
from pathlib import Path


def _check_finite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
    elif isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text)
    except ValueError:
        raise ValueError("invalid JSON")
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _check_finite(data)
    return data

def _clean(text):
    parts = text.split()
    s = " ".join(parts)
    return s.strip(" \t\r\n/:,;")


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


_TAG_CATEGORY = {
    "600": "people",
    "610": "organizations",
    "611": "meetings",
    "630": "works",
    "650": "topics",
    "651": "places",
}


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    src = _unwrap(payloads[0])
    records = src["records"]

    out_records = []
    for rec in records:
        rid = rec["id"]
        fields = rec.get("fields", [])
        categories = {
            "people": {},
            "organizations": {},
            "meetings": {},
            "works": {},
            "topics": {},
            "places": {},
        }
        for f in fields:
            tag = f.get("tag")
            cat = _TAG_CATEGORY.get(tag)
            if cat is None:
                continue
            subfields = f.get("subfields", [])
            main_parts = []
            sub_parts = []
            for sf in subfields:
                code = sf.get("code")
                value = sf.get("value", "")
                if code in ("a", "b"):
                    main_parts.append(value)
                elif code in ("v", "x", "y", "z"):
                    sub_parts.append(_clean(value))
            main = _clean(" ".join(main_parts))
            full = main
            if sub_parts:
                full = main + " -- " + " -- ".join(sub_parts)
            categories[cat][full] = categories[cat].get(full, 0) + 1

        subjects = {}
        for cat in ("people", "organizations", "meetings", "works", "topics", "places"):
            items = [
                {"value": v, "count": c}
                for v, c in sorted(categories[cat].items())
            ]
            subjects[cat] = items

        out_records.append({"id": rid, "subjects": subjects})

    return {"name": contract["name"], "result": {"records": out_records}}

import json
import math
from pathlib import Path


def _check_finite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
    elif isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text)
    except ValueError:
        raise ValueError("invalid JSON")
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _check_finite(data)
    return data

def _unwrap(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    names = _unwrap(payloads[0])
    languages = _unwrap(payloads[1])
    subjects = _unwrap(payloads[2])

    def index(records):
        result = {}
        for r in records:
            rid = r["id"]
            if rid in result:
                raise ValueError("duplicate record id")
            result[rid] = r
        return result

    names_idx = index(names["records"])
    langs_idx = index(languages["records"])
    subs_idx = index(subjects["records"])

    ids = set(names_idx)
    if set(langs_idx) != ids or set(subs_idx) != ids:
        raise ValueError("record id sets must match")

    records = []
    for rid in sorted(ids):
        records.append({
            "id": rid,
            "authors": names_idx[rid]["authors"],
            "titles": names_idx[rid]["titles"],
            "languages": langs_idx[rid]["languages"],
            "subjects": subs_idx[rid]["subjects"],
        })

    return {
        "name": contract["name"],
        "result": {"records": records, "record_count": len(records)},
    }

